	public void stopServer(Map<String, String> objDictionary) 
	{	
		//Kill Existing AppiumPort
		String strDeviceAppiumPort = objDictionary.get("strDeviceAppiumPort");
		if(strDeviceAppiumPort == null)
		{strDeviceAppiumPort = System.getProperty("strDeviceAppiumPort");}
		//Test Code Connection refused (Connection refused)
		String[] command3 = {"sh", "-c", "ps -ef | grep "+strDeviceAppiumPort+"| awk '{print $2'} | xargs kill -9"};
		try 
		{
			Runtime.getRuntime().exec(command3);
			System.out.println("Appium server stopped. Port("+strDeviceAppiumPort+")");
		}catch (IOException e) {e.printStackTrace();}
		try {Thread.sleep(5000);}catch (Exception e) {}
		String timeStamp = new SimpleDateFormat("HH.mm.ss").format(new Date());
		Reporter.log("Appium server stopped-"+timeStamp);
	}
	public void startServer(Map<String, String> objDictionary) {
	    String strDeviceAppiumPort = objDictionary.get("strDeviceAppiumPort");
	    String strAutomationUser = System.getProperty("user.name");
	    // Used when executing from Jenkins
	    if (strAutomationUser.equals("jenkins")) {
	        strAutomationUser = "mpsadmin";
	    }
	    Reporter.log("Start Server Automation User: " + strAutomationUser);

	    try {
	        // Dynamically get paths to node and appium
	        String nodePath = getBinaryPath("node");
	        String appiumPath = getBinaryPath("appium");

	        if (nodePath == null || appiumPath == null) {
	            throw new IOException("Could not find node or appium in PATH");
	        }

	        // Start Appium server
	        CommandLine command = new CommandLine(nodePath);
	        command.addArgument(appiumPath, false);
	        command.addArgument("--address", false);
	        command.addArgument("127.0.0.1");
	        command.addArgument("--port", false);
	        command.addArgument(strDeviceAppiumPort);
	        command.addArgument("--session-override", true);

	        DefaultExecuteResultHandler resultHandler = new DefaultExecuteResultHandler();
	        DefaultExecutor executor = new DefaultExecutor();
	        executor.setExitValue(1);

	        executor.execute(command, resultHandler);
	        Thread.sleep(5000); // Wait for server to start
	        String timeStamp = new SimpleDateFormat("HH.mm.ss").format(new Date());
	        System.out.println("Appium server started-" + timeStamp);
	        Reporter.log("Appium server started-" + timeStamp);
	    } catch (IOException e) {
	        e.printStackTrace();
	        Reporter.log("Failed to start Appium server: " + e.getMessage());
	    } catch (InterruptedException e) {
	        e.printStackTrace();
	        Reporter.log("Appium server startup interrupted: " + e.getMessage());
	    }

	    checkIfServerIsRunnning(Integer.parseInt(strDeviceAppiumPort));
	}
	private String getBinaryPath(String binaryName) throws IOException {
	    ProcessBuilder pb = new ProcessBuilder("which", binaryName);
	    Process process = pb.start();
	    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
	        String path = reader.readLine();
	        if (path != null && !path.trim().isEmpty()) {
	            return path.trim();
	        }
	    }
	    return null;
	}

	public boolean checkIfServerIsRunnning(int port) 
    {
    	boolean isServerRunning = false;
    	ServerSocket serverSocket;
    	try 
    	{
    		serverSocket = new ServerSocket(port);
    		serverSocket.close();
    	} 
    	catch (IOException e) 
    	{
    		//If control comes here, then it means that the port is in use
    		isServerRunning = true;
		 } finally {serverSocket = null;}
		 return isServerRunning;
    }
