	public AppiumDriver SetMobileDriver(Map<String, String> objDictionary, String strApplication, String strGPSEnabled, String strRole) 
	{
		ADB_Commands clsADBcommands = new ADB_Commands();
		String strStopAndStartAppiumServer = objDictionary.getOrDefault("strStopAndStartAppiumServer", "false");
	    String strAndroidUdid = objDictionary.getOrDefault("strAndroidUdid", "R5CT71MQ2MM");
	    String strDeviceAppiumPort = objDictionary.getOrDefault("strDeviceAppiumPort", "4723");
	    String strMobileAPK = objDictionary.get("strMobileAPK");
	    int port = Integer.parseInt(strDeviceAppiumPort);
	    ensureAdbServerRunning();
	    //Disable Airplane Mode Before Setting other ADB Commands
	    String strOriginalAirplaneMode = objDictionary.get("strAirplaneMode");if(strOriginalAirplaneMode == null) {strOriginalAirplaneMode = "Disabled";}
	    objDictionary.put("strAirplaneMode","Disabled");
	    clsADBcommands.SENTRYMOBILE_SET_AIRPLANE_MODE(objDictionary);
	    objDictionary.put("strAirplaneMode",strOriginalAirplaneMode);
	    //Set ADB Commands
	    clsADBcommands.SENTRYMOBILE_SET_WIFI(objDictionary);
	    clsADBcommands.SENTRYMOBILE_SET_WIFIScanning(objDictionary);
	    
	    clsADBcommands.SENTRYMOBILE_SET_AIRPLANE_MODE(objDictionary);
	    
	    // === Start Appium Server Automatically (Only if flag is true) ===
	    boolean shouldStartServer = Boolean.parseBoolean(strStopAndStartAppiumServer);
	    if (shouldStartServer) {

	        // 1. Kill anything currently using the port
	        killProcessOnPort(port);

	        // 2. Stop any previous service we started
	        if (appiumService != null && appiumService.isRunning()) {
	            appiumService.stop();
	        }

	        // 3. Dynamically find Node and Appium
	        String nodePath = findExecutable("node");
	        String appiumJSPath = findAppiumMainJs();

	        System.out.println("Using Node: " + nodePath);
	        System.out.println("Using Appium JS: " + appiumJSPath);

	        AppiumServiceBuilder builder = new AppiumServiceBuilder()
	                .usingDriverExecutable(new File(nodePath))
	                .withAppiumJS(new File(appiumJSPath))
	                .withIPAddress("127.0.0.1")
	                .usingPort(port)
	                .withArgument(GeneralServerFlag.LOG_LEVEL, "info");

	        appiumService = AppiumDriverLocalService.buildService(builder);
	        appiumService.start();

	        if (!appiumService.isRunning()) {
	            System.err.println("Appium server failed to start!");
	            return null;
	        }

	        System.out.println("Appium server started at: " + appiumService.getUrl());

	        // Give server a moment to fully initialize
	        try {
	            Thread.sleep(5000);
	        } catch (InterruptedException e) {
	            Thread.currentThread().interrupt();
	        }
	    }

	    setupDeviceEnvironment(strAndroidUdid);

	    // Dynamically find APK path
	    String apkBasePath = findApkBasePath();
	    String fullApkPath = apkBasePath + strMobileAPK;
	    System.out.println("Using APK: " + fullApkPath);

	    // Configure UiAutomator2Options
	    UiAutomator2Options options = new UiAutomator2Options()
	            .setPlatformName("Android")
	            .setPlatformVersion("15")
	            .setDeviceName(strRole)
	            .setUdid(strAndroidUdid)
	            .setApp(fullApkPath);

	    options.setCapability("autoGrantPermissions", true);
	    options.setCapability("noReset", false);
	    options.setCapability("fullReset", true);
	    options.setCapability("appWaitActivity", "*");
	    if (strApplication.equals("PEO")) {
	        options.setCapability("appWaitPackage", "com.mpspark.mobileOfficer");
	    } else {
	        options.setCapability("appWaitPackage", "com.mpspark.consumer.mpsconsumer");
	    }
	    options.setCapability("disableWindowAnimation", true);
	    options.setCapability("skipUnlock", true);
	    options.setCapability("appium:unicodeKeyboard", true);
	    options.setCapability("newCommandTimeout", 3600);

	    options.setCapability("appium:enableNotificationListener", true);

	    // Testing for Google Map issue
	    options.setCapability("clearSystemFiles", true);

	    AppiumDriver androidDriver = null;
	    try {
	        URL serverUrl = shouldStartServer ? appiumService.getUrl() : URI.create("http://127.0.0.1:" + port).toURL();

	        System.out.println("Connecting to Appium at: " + serverUrl);
	        androidDriver = new AppiumDriver(serverUrl, options);
	        System.out.println("Session created successfully!");
	    } catch (Exception e) {
	        System.err.println("Failed to initialize driver:");
	        e.printStackTrace();
	        return null;
	    }

	    if (!"PEO".equals(strApplication)) {
	        try {
	            SENTRYMOBILE_CheckUserAccountBalanceAddFundsIfNeeded(objDictionary, strRole);
	        } catch (Exception e) {
	        }
	    }
	    SENTRYMOBILE_SETGPSSettings(objDictionary, androidDriver, strGPSEnabled);
	    Reporter.log("Sentry Mobile was loaded correctly on Android Device");

	    return androidDriver;
	}
	// ==================== HELPER METHODS ====================

	private void killProcessOnPort(int port) {
	    try {
	        Process process = new ProcessBuilder("lsof", "-t", "-i", ":" + port).start();
	        try (java.io.BufferedReader reader = new java.io.BufferedReader(
	                new java.io.InputStreamReader(process.getInputStream()))) {
	            String pid;
	            while ((pid = reader.readLine()) != null) {
	                System.out.println("Killing process on port " + port + " (PID: " + pid + ")");
	                new ProcessBuilder("kill", "-9", pid.trim()).start().waitFor();
	            }
	        }
	        Thread.sleep(1000); // give the OS time to release the port
	    } catch (Exception e) {
	        System.out.println("No process found on port " + port + " (or failed to kill): " + e.getMessage());
	    }
	}

	private String findExecutable(String command) {
	    try {
	        Process process = new ProcessBuilder("which", command).start();
	        try (java.io.BufferedReader reader = new java.io.BufferedReader(
	                new java.io.InputStreamReader(process.getInputStream()))) {
	            String path = reader.readLine();
	            if (path != null && !path.isEmpty()) {
	                return path.trim();
	            }
	        }
	    } catch (Exception e) {
	        System.err.println("Could not find " + command + " in PATH");
	    }
	    throw new RuntimeException("Could not find executable: " + command);
	}

	private String findAppiumMainJs() {
	    String home = System.getProperty("user.home");
	    String[] possiblePaths = {
	        home + "/.nvm/versions/node/v24.12.0/lib/node_modules/appium/build/lib/main.js",
	        home + "/.nvm/versions/node/v20.11.0/lib/node_modules/appium/build/lib/main.js",
	        home + "/.nvm/versions/node/v22.14.0/lib/node_modules/appium/build/lib/main.js",
	        home + "/.nvm/versions/node/v20.18.0/lib/node_modules/appium/build/lib/main.js",
	        "/usr/local/lib/node_modules/appium/build/lib/main.js",
	        "/opt/homebrew/lib/node_modules/appium/build/lib/main.js"
	    };

	    for (String path : possiblePaths) {
	        if (new File(path).exists()) {
	            return path;
	        }
	    }

	    // Fallback via npm
	    try {
	        Process process = new ProcessBuilder("npm", "root", "-g").start();
	        try (java.io.BufferedReader reader = new java.io.BufferedReader(
	                new java.io.InputStreamReader(process.getInputStream()))) {
	            String npmRoot = reader.readLine();
	            if (npmRoot != null) {
	                String candidate = npmRoot.trim() + "/appium/build/lib/main.js";
	                if (new File(candidate).exists()) {
	                    return candidate;
	                }
	            }
	        }
	    } catch (Exception ignored) {}

	    throw new RuntimeException("Could not find Appium main.js on this machine");
	}

	private String findApkBasePath() {
	    String home = System.getProperty("user.home");
	    String[] possibleBases = {
	        home + "/git/MPS-Flutter-Automation/APK/",
	        home + "/git/TestAutomation/APK/",
	        home + "/git/Legacy-TestAutomation/APK/",
	        System.getProperty("user.dir") + "/APK/"
	    };

	    for (String path : possibleBases) {
	        if (new File(path).exists()) {
	            return path;
	        }
	    }
	    return System.getProperty("user.dir") + "/APK/";
	}
	public void SENTRYMOBILE_SETGPSSettings(Map<String, String> objDictionary, AppiumDriver androidDriver, String strGPSEnabled) {
	    String strLocation = objDictionary.get("strLocation");
	    String strAutomationUser = System.getProperty("user.name");
	    String strDeviceName = (String) androidDriver.getCapabilities().getCapability("deviceName");
	    int intAndroidVersion = METER_ADB_GetAndriodVersion(strDeviceName, "getprop ro.build.version.release");
	    String adbPath = "/Users/" + strAutomationUser + "/Library/Android/sdk/platform-tools/adb";

	    int targetMode = strGPSEnabled.equals("True") ? 3 : 0;  // 3 = High Accuracy, 0 = Off
	    String action = (targetMode == 3) ? "enable" : "disable";

	    // Log current state BEFORE change
	    try {
	        Process preVerify = Runtime.getRuntime().exec(adbPath + " -s " + strDeviceName + " shell settings get secure location_mode");
	        BufferedReader preReader = new BufferedReader(new InputStreamReader(preVerify.getInputStream()));
	        String preOutput = preReader.readLine();
	        Reporter.log("Location mode BEFORE " + action + ": " + (preOutput != null ? preOutput.trim() : "unknown"));
	    } catch (Exception ignored) {}

	    try {
	        String cmd = adbPath + " -s " + strDeviceName + " shell settings put secure location_mode " + targetMode;
	        Reporter.log("Executing ADB command: " + cmd);

	        Process process = Runtime.getRuntime().exec(cmd);
	        int exitCode = process.waitFor();

	        if (exitCode == 0) {
	            Reporter.log("Location services " + action + "d successfully (mode " + targetMode + " - exit code 0)");
	        } else {
	            UpdateErrorMessageWithPivotalData(objDictionary, androidDriver,
	                "Failed to " + action + " location services via ADB (exit code: " + exitCode + ")");
	            // Optional fallback: try Appium toggle (only flips basic on/off, may not set high accuracy)
	            try {
	                ((AndroidDriver) androidDriver).toggleLocationServices();
	                Reporter.log("Fallback: Used Appium toggleLocationServices() after ADB failure");
	            } catch (Exception toggleEx) {
	                Reporter.log("Appium fallback also failed: " + toggleEx.getMessage());
	            }
	        }

	        // Small delay to let system catch up
	        Thread.sleep(1500);

	        // Verify AFTER
	        try {
	            Process verifyProcess = Runtime.getRuntime().exec(adbPath + " -s " + strDeviceName + " shell settings get secure location_mode");
	            BufferedReader reader = new BufferedReader(new InputStreamReader(verifyProcess.getInputStream()));
	            String output = reader.readLine();
	            String verifiedMode = (output != null ? output.trim() : "unknown");
	            Reporter.log("Location mode AFTER " + action + ": " + verifiedMode);

	            // Optional: fail test if not matching target
	            if (!verifiedMode.equals(String.valueOf(targetMode))) {
	                UpdateErrorMessageWithPivotalData(objDictionary, androidDriver,
	                    "Location mode mismatch after set attempt! Expected: " + targetMode + ", Got: " + verifiedMode);
	            }
	        } catch (Exception verifyEx) {
	            UpdateErrorMessageWithPivotalData(objDictionary, androidDriver, "Could not verify location_mode: " + verifyEx.getMessage());
	        }

	    } catch (Exception e) {
	        UpdateErrorMessageWithPivotalData(objDictionary, androidDriver, "Error while trying to " + action + " location via ADB: " + e.getMessage());
	    }

	    objDictionary.put("strGPSEnabled", strGPSEnabled);
	}
	private void setupDeviceEnvironment(String strAndroidUdid) {
        String adbPath = System.getenv("ANDROID_HOME");
        if (adbPath == null) {
            throw new IllegalStateException("ANDROID_HOME environment variable is not set");
        }
        adbPath += "/platform-tools/adb";
        try {
            // Verify device connection
            String devices = executeAdbCommand(adbPath + " devices");
            if (!devices.contains(strAndroidUdid)) {
                throw new IllegalStateException("Device with UDID " + strAndroidUdid + " not found.");
            }

            // Set logcat buffer size
            executeAdbCommand(String.format("%s -s %s logcat -G 10M", adbPath, strAndroidUdid));

            // Stop and uninstall packages
            String[] packages = {
                "io.appium.uiautomator2.server",
                "io.appium.uiautomator2.server.test",
                "com.mpspark.consumer.mpsconsumer"
            };
            for (String pkg : packages) {
                try {
                    // Stop package
                    executeAdbCommand(String.format("%s -s %s shell am force-stop %s", adbPath, strAndroidUdid, pkg));
                    // Check if package exists before uninstalling
                    String result = executeAdbCommand(String.format("%s -s %s shell pm list packages | grep %s", adbPath, strAndroidUdid, pkg));
                    if (!result.isEmpty()) {
                        executeAdbCommand(String.format("%s -s %s uninstall %s", adbPath, strAndroidUdid, pkg));
                    } else {
                        System.out.println("Package " + pkg + " not found, skipping uninstall.");
                    }
                } catch (IOException | InterruptedException e) {
                    System.err.println("Failed to process package " + pkg + ": " + e.getMessage());
                }
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Failed to set up device environment: " + e.getMessage());
        }
    }
	private String executeAdbCommand(String command) throws IOException, InterruptedException {
       Process process = Runtime.getRuntime().exec(command);
       StringBuilder output = new StringBuilder();
       StringBuilder errorOutput = new StringBuilder();
       try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
           String line;
           while ((line = reader.readLine()) != null) {
               output.append(line).append("\n");
           }
       }
       try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
           String line;
           while ((line = errorReader.readLine()) != null) {
               errorOutput.append(line).append("\n");
           }
       }
       int exitCode = process.waitFor();
       if (exitCode != 0) {
           throw new IOException("Command failed: " + command + "\nError: " + errorOutput.toString());
       }
       return output.toString();
	}
	private void ensureAdbServerRunning() {
		try {
	        Process process = Runtime.getRuntime().exec("adb devices");
	        process.waitFor();
	        if (process.exitValue() != 0) {
	            System.out.println("ADB server not running, restarting...");
	            Runtime.getRuntime().exec("adb kill-server");
	            Thread.sleep(1000);
	            Runtime.getRuntime().exec("adb start-server");
	            Thread.sleep(2000);
	        }
	        // Verify devices are detected
	        process = Runtime.getRuntime().exec("adb devices");
	        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
	        String line;
	        boolean deviceFound = false;
	        boolean unauthorizedFound = false;
	        while ((line = reader.readLine()) != null) {
	        	 if (line.endsWith("device")) {
	        	        deviceFound = true;
	        	    } else if (line.contains("unauthorized")) {
	        	        unauthorizedFound = true;
	        	        // Optionally break if you don't want to process further
	        	    }
	        }
	        if (unauthorizedFound) {
	            throw new RuntimeException("Device detected but UNAUTHORIZED. " +
	                "Please unlock the device and approve the 'Allow USB debugging' RSA key popup. " +
	                "Check 'Always allow from this computer' to avoid this in the future.");
	        }
	        if (!deviceFound) {
	            throw new RuntimeException("No Android devices/emulators detected. " +
	                "Ensure a device/emulator is connected and ADB is working (run 'adb devices' manually to debug).");
	        }	    } catch (IOException | InterruptedException e) {
	        throw new RuntimeException("Failed to ensure ADB server is running: " + e.getMessage());
	    }
	}
	
