	public void NotitificationHandler(Map<String, String> objDictionary, AppiumDriver androiddriver)
	{
		//This is need for 
		try {androiddriver.findElement(By.id("com.android.permissioncontroller:id/permission_allow_button")).click();}catch(Exception a) {};
		String strNotificationSetting = objDictionary.get("strNotificationSetting");if(strNotificationSetting == null) {strNotificationSetting = "False";}
        try 
	    {
	    	if(strNotificationSetting.equals("False"))
	    	{
	    		androiddriver.findElement(By.id("com.mpspark.consumer.mpsconsumer:id/textViewClose")).click();try {Thread.sleep(500);}catch (Exception e) {}
	    	}
	    	else
	    	{
	    		Boolean isPresent = androiddriver.findElements(By.id("com.mpspark.consumer.mpsconsumer:id/textViewClose")).size() > 0;
	    		if(isPresent.equals(true))
	    		{
	    			//Validate Notification was sent from Sentry Link
	    			String strNotificationResponse = objDictionary.get("strNotificationResponse");if(strNotificationResponse == null) {strNotificationResponse = "Close";}
	    			if(strNotificationResponse.equals("Close"))
	    			{
	    				androiddriver.findElement(By.id("com.mpspark.consumer.mpsconsumer:id/textViewClose")).click();
	    			}
	    		}
	    	}
	    }catch(Exception a) {};
	}
	
