	public void DismissNotification(AppiumDriver androidDriver) {
	    
		try {Thread.sleep(4000);}catch (Exception e) {}
		// Center of the notification: (540, 133)
	    PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");

	    Sequence tapSequence = new Sequence(finger, 0)
	        .addAction(finger.createPointerMove(Duration.ZERO, PointerInput.Origin.viewport(), 540, 133))
	        .addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
	        .addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

	    androidDriver.perform(Arrays.asList(tapSequence));
	}
	public void PopulateAction(Map<String, String> objDictionary, AppiumDriver androiddriver, String strPageName, String strAction, String strObjectNames,String strObjectValues)
	{	
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		String[] arrObjectNames = strObjectNames.split("\\|", -1);
		String[] arrObjectValues = strObjectValues.split("\\|", -1);
		int intCounter = 0;		
		String strObjectnameWithValues = "";
		for (String strObjectName : arrObjectNames)
        {
			 String[] arrObjectName = strObjectName.split("}");
			 String strObjectType = arrObjectName[0].substring(1);
    		 strObjectName = arrObjectName[1].substring(1);
    		 if(!arrObjectValues[intCounter].equals(""))
             {
	             switch (strObjectType)
	             {
	             	case "CB":
	             		PopulateCheckbox(objDictionary, androiddriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	             		break;
	             	case "L":
	             	case "UDL":
	             		PopulateListbox(objDictionary, androiddriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	case "T":
	             		PopulateTextfield(objDictionary, androiddriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	case "RB":
	             		PopulateRadioButton(objDictionary,androiddriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	default:
	             		clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Object Type(" + strObjectType + ") does not exist or has not been coded-"+strMethodName);
	             }
             }
             try {Thread.sleep(700);}catch (Exception e) {}
             strObjectnameWithValues = strObjectnameWithValues+"|"+strObjectName+","+arrObjectValues[intCounter];
             intCounter++;
        }
		String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
		strObjectnameWithValues = strObjectnameWithValues.substring(1);
		if (strStoredPopulateVariable != null)                        
        {
			Reporter.log("The (" + strAction.replaceAll("Populate ", "") + ") field(s) were populated correctly (" + strStoredPopulateVariable + ") - Values("+strObjectnameWithValues+")");
		 	objDictionary.remove("strStoredPopulateVariable");
        }
        else
        { Reporter.log("The (" + strAction.replaceAll("Populate ", "") + ") field(s) were populated correctly - Values("+strObjectnameWithValues+")");}
 	}
