	public void PopulateCheckboxWithinScrollableList(Map<String, String> objDictionary, AndroidDriver androiddriver, String strPageName, String strTextName, String strScrollableListboxName)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		CommonANDROID clsCommonMobile = new CommonANDROID();
		String strCondition = "False";String strLastItemBeforeScroll = "";String strLastItemAfterScroll = "";
		WebElement objScrollableListContainer = GetScrollableListContainerObj(objDictionary,androiddriver, strPageName, strScrollableListboxName); 
		do
	    {
			List<WebElement> lsItemsBeforeScroll = null;
			try {Thread.sleep(2000);}catch (Exception e) {}
			try{lsItemsBeforeScroll = androiddriver.findElements(By.id("com.mpspark.mobileOfficer:id/textViewMeterGroupName"));}
			catch(Exception e)
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The item before scroll did not exist-"+strMethondName);}
			if(lsItemsBeforeScroll.size() == 0){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"There was no Items in the ScrollableListboxName ("+strScrollableListboxName+")-"+strMethondName);}
			strLastItemBeforeScroll = lsItemsBeforeScroll.get(lsItemsBeforeScroll.size() - 1).getText();
			strCondition = ConditionalStepText(objDictionary,androiddriver, strPageName, strTextName, 1, "Exists",  "");
			if(strCondition.equals("False"))
			{
				ElementSwipe  clsElementSwipe  = new ElementSwipe();
				clsElementSwipe.Swipe(androiddriver,objScrollableListContainer,"SWIPE_UP"); 
				strCondition = ConditionalStepText(objDictionary,androiddriver, strPageName, strTextName, 1, "Exists",  "");
			}
			List<WebElement> lsItemsAfterScroll =  null;
			try{lsItemsAfterScroll = androiddriver.findElements(By.id("com.mpspark.mobileOfficer:id/textViewMeterGroupName"));}
			catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The item after scroll did not exist-"+strMethondName);}
			if(strCondition.equals("True"))
			{
				for(int i=0;i<lsItemsAfterScroll.size();i++)
				{
					if(lsItemsAfterScroll.get(i).getText().equals(strTextName))
					{
						try
						{
							//This path will change when similar component exists.
							WebElement objCheckbox = androiddriver.findElement(By.xpath("//android.widget.LinearLayout[1]/android.widget.FrameLayout[1]/android.widget.RelativeLayout[1]/android.widget.ListView[1]/android.widget.LinearLayout["+(i+1)+"]/android.widget.CheckBox[1]"));
							if (objCheckbox.getAttribute("checked").equals("false")){objCheckbox.click();}
							Reporter.log("The ("+strTextName+") checkbox was checked"+"");
							return;
						}
						catch (Exception e) 
						{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The ("+strTextName+") checkbox did not exist or the object properties have changed-"+strMethondName);}
					}
				}
			}
			strLastItemAfterScroll = lsItemsAfterScroll.get(lsItemsAfterScroll.size() - 1).getText();
			if(strLastItemBeforeScroll.equals(strLastItemAfterScroll)){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Text (" + strTextName + ") did not exist in the ScrollableListbox ("+strScrollableListboxName+")-"+strMethondName);}
		 }while (strCondition == "False");
	}
