	public void PopulateTextfield(Map<String, String> objDictionary,AppiumDriver androiddriver, String strPageName, String strObjectName, String strObjectValue)
	{	
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		WebElement objTextField = GetTextFieldObj(objDictionary, androiddriver, strPageName, strObjectName);
		if(objTextField == null) {clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield ("+strObjectName+") was null check if the object properties have changed");}
		strObjectValue = ConvertValues(objDictionary, androiddriver, strObjectValue);
		if (strTextfieldPopulateType == "JQueryTextField")
		{
			if(strSpecialInstruction.equals("ClearField"))
			{
				objTextField.clear();
				strSpecialInstruction = "";
			}
			strTextfieldPopulateType = "";
			if (androiddriver instanceof JavascriptExecutor) 
			{
				try{((JavascriptExecutor)androiddriver).executeScript("document.getElementById('"+strJQueryFilter+"').value = \""+strObjectValue+"\";");}
				catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield (" + strObjectName + ")  did not exist");}
			}
			else 
			{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"This androiddriver does not support JavaScript!");}
			strTextfieldPopulateType = "";strJQueryFilter = "";
		}
 		else if (strTextfieldPopulateType == "SendKey")
		{
			if(strSpecialInstruction.equals("ClearField"))
			{
				try{objTextField.clear();}
				catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"Error attempting to clear Textfield (" + strObjectName + ")-"+e);};
				strSpecialInstruction = "";
			}
			if(strObjectValue.equals("Blank"))
			{
				try {objTextField.sendKeys("");}catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield (" + strObjectName + ")  did not exist");}
			}
			else
			{
				try {objTextField.sendKeys(strObjectValue);}catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield (" + strObjectName + ")  did not exist");}
			}
			try {Thread.sleep(1000);}catch (Exception e) {}
		}
		else if (strTextfieldPopulateType == "SendKeyAndClick")
		{
			if(strSpecialInstruction.equals("ClearField"))
			{
				try{objTextField.clear();}
				catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"Error attempting to clear Textfield (" + strObjectName + ")-"+e);};
				strSpecialInstruction = "";
			}
			try {objTextField.sendKeys(strObjectValue);}catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield (" + strObjectName + ")  did not exist");}
			try {Thread.sleep(1000);}catch (Exception e) {}
			objTextField.click();
		}
		else
		{	
			if (objTextField != null)
		    {
		    	if(strSpecialInstruction.equals("ClearField"))
		    	{
		    		objTextField.click(); objTextField.clear(); objTextField.sendKeys(""); strSpecialInstruction = "";
		    	}
		    	String strAutomationUser = System.getProperty("user.name");
		    	if(strAutomationUser.equals("jenkins")){strAutomationUser = "mpsadmin";}
		        String strDeviceName = (String)androiddriver.getCapabilities().getCapability("deviceName");
		    	objTextField.click();
		    	if(strSpecialInstruction == "Lowercase"){strObjectValue = strObjectValue.toLowerCase();}strSpecialInstruction = "";
	    		if(strAutomationUser.equals("Padma")){strAutomationUser = "chris";}
		    	try{Runtime.getRuntime().exec("/Users/"+strAutomationUser+"/Library/Android/sdk/platform-tools//adb -s "+strDeviceName+" shell input text "+strObjectValue);}
	    		catch(Exception e){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield (" + strObjectName + ") did not exist");}
		    	try {Thread.sleep(1000);}catch (Exception e) {}
		    }
		    else
	  		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androiddriver,"The Textfield (" + strObjectName + ") did not exist");}
		}
		if (strStoreValueAsVariableName != "")
        {
            objDictionary.remove(strStoreValueAsVariableName); objDictionary.put(strStoreValueAsVariableName, strObjectValue);
            String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
            if (strStoredPopulateVariable != null)
            {objDictionary.remove("strStoredPopulateVariable");objDictionary.put("strStoredPopulateVariable", strStoredPopulateVariable + strStoreValueAsVariableName + ": " + strObjectValue + "|");}
            else
            { objDictionary.put("strStoredPopulateVariable", strStoreValueAsVariableName + ": " + strObjectValue + "|"); }
            strStoreValueAsVariableName = "";
        }
	}
