	public String SENTRYMOBILE_BuyMaxTime(Map<String, String> objDictionary,AppiumDriver androidDriver, int intTotalMaxTimeMin,String strPaymentNbr)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
    	Meter clsMeter = new Meter();
    	HttpConnections clsHttpConnections = new HttpConnections();
		clsCommonMobile.ClickButton(objDictionary, androidDriver, "Choose Parking Duration", "Buy Max Time", 1);
		clsCommonMobile.ClickButton(objDictionary, androidDriver, "Choose Parking Duration", "Proceed", 1);
		//Validate Total Amount
		String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
		String strSecondRateStartTime = objDictionary.get("strSecondRateStartTime");
		String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
		DecimalFormat dFormat = new DecimalFormat("$ 0.00");
		//Check For Fees
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strTotalFee = "0";
		if(strPaymentNbr.equals("1"))
		{
			String strFirstPayment = objDictionary.get("strFirstPayment");//First Payment Fee
			//intTotalMaxTimeMin = (int)Math.ceil(intTotalMaxTimeMin/Double.parseDouble(strMeterIncrementTime)) * Integer.parseInt(strMeterIncrementTime);
			if (strFirstPayment != null)
			{
				//strSecondRateStartTime comes from: SENTRYLINK_SetRateBlocksRateToRate - Not sure how it's used
				if(strSecondRateStartTime != null)
				{
					int intRemainingMinutesInFirstRateSet = clsMeter.METER_CalculateRemainingMinutesBeforeNextRate(objDictionary, null, strSecondRateStartTime)-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes First Rateblock: "+intRemainingMinutesInFirstRateSet);
					int intNumberOfPaymentInFirsttRateSet = intRemainingMinutesInFirstRateSet/12;
					int intRemainingMinutes = intRemainingMinutesInFirstRateSet - intNumberOfPaymentInFirsttRateSet * 12;
					Reporter.log("intRemainingMinutes: "+intRemainingMinutes);
					String strTotalFeeFirstRateSet = "$" + dFormat.format((int)Math.ceil(((double)intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime)) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 1st Rate Block Equaled: "+strTotalFeeFirstRateSet);
					int intMinutesInSecondRateSet = intTotalMaxTimeMin - intRemainingMinutesInFirstRateSet-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes Second Rateblock: "+intMinutesInSecondRateSet);
					String strTotalFeeSecondRateSet = "$" + dFormat.format((int)Math.ceil(((double)intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 2nd Rate Block Equaled: "+strTotalFeeSecondRateSet);
					String strFirstTimePaymentFee = "$" + dFormat.format((Integer.parseInt(strFirstPayment)*.01));
					Reporter.log("First Payment Fee: "+strFirstTimePaymentFee);
					objDictionary.put("strFirstTimePaymentFee",strFirstTimePaymentFee);//Used SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues
					strTotalFee = "$" + dFormat.format((int)Math.ceil(((double)intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime)) * (Double.parseDouble(strMeterNextRateCost)/100) + (int)Math.ceil(((double)intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100) + Integer.parseInt(strFirstPayment)*.01);
				}
				else
				{
					String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");
					String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
		    		if(strRemainingFreeTimeStart != null)
		    		{
						int intRemainingFreeMinutes = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes);
			    		clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment)-intRemainingFreeMinutes)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)));
						clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(Integer.parseInt(strFirstPayment)*.01));
						strTotalFee = dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment) - intRemainingFreeMinutes)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)+ (Integer.parseInt(strFirstPayment)*.01));
		    		}
		    		else
		    		{
		    			String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
		    			if(strMinutesBeforeFreeStart != null)
		    			{
		    				int intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
							String strParkingFee = dFormat.format(Math.ceil(intMeterRemainingTimeMinutes / (double) Integer.parseInt(strMeterIncrementTime))* (Double.parseDouble(strMeterNextRateCost) / 100));
							clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Parking Fee", 1, "Contains", strParkingFee);
							clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(Integer.parseInt(strFirstPayment)*.01));
							strTotalFee = dFormat.format(Math.ceil(intMeterRemainingTimeMinutes / (double) Integer.parseInt(strMeterIncrementTime))* (Double.parseDouble(strMeterNextRateCost) / 100)+ (Integer.parseInt(strFirstPayment)*.01));
						 	objDictionary.put("strMeterRemainingTimeMinutes", Integer.toString(intMeterRemainingTimeMinutes));
		    			}
					 	else
						{
					 		clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)));
							clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(Integer.parseInt(strFirstPayment)*.01));
							strTotalFee = dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)+ (Integer.parseInt(strFirstPayment)*.01));
						}
		    		}
				}
			}
			else
			{
				if(strSecondRateStartTime != null)
				{
					int intRemainingMinutesInFirstRateSet = clsMeter.METER_CalculateRemainingMinutesBeforeNextRate(objDictionary, null, strSecondRateStartTime)-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes First Rateblock: "+intRemainingMinutesInFirstRateSet);
					int intMinutesInSecondRateSet = intTotalMaxTimeMin - intRemainingMinutesInFirstRateSet;
					Reporter.log("Remaining Minutes Second Rateblock: "+intMinutesInSecondRateSet);

					String strTotalFeeFirstRateSet = "$" + dFormat.format((intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 1st Rate Block Equaled: "+strTotalFeeFirstRateSet);

					String strTotalFeeSecondRateSet = "$" + dFormat.format((intMinutesInSecondRateSet)/ 10 * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 2nd Rate Block Equaled: "+strTotalFeeSecondRateSet);
					strTotalFee = "$" + dFormat.format(((intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime) + (intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100));
				}
				else
				{
					strTotalFee = "$" + dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100));
				}
			}
			clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Total Fee", 1, "Contains", strTotalFee);
		}
		else
		{
			String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
			intTotalMaxTimeMin = (int)Math.ceil(intTotalMaxTimeMin/Double.parseDouble(strMeterIncrementTime)) * Integer.parseInt(strMeterIncrementTime);
			if (strSubsequentPayment != null)
			{strTotalFee = "$" + dFormat.format(intTotalMaxTimeMin / Integer.parseInt(strMeterIncrementTime) * Integer.parseInt(strMeterNextRateCost)/100 + (Integer.parseInt(strSubsequentPayment)*.01));}
			else
			{
				strTotalFee = "$" + dFormat.format(intTotalMaxTimeMin / Double.parseDouble(strMeterIncrementTime) * Double.parseDouble(strMeterNextRateCost)/100);
			}
			clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Total Fee", 1, "Contains", strTotalFee);
		}
		objDictionary.put("strTotalFee",strTotalFee);//Used SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues//SENTRYMOBILE_BuyMaxTime
		return strTotalFee;
	}
	
	public void SENTRYMOBILE_DeleteSavedCreditCards(Map<String, String> objDictionary, AppiumDriver androidDriver)
	{
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		//Delete Saved Credit Card - Function
		clsCommonMobile.NavigateToPageUsingMenuButtons(objDictionary,androidDriver, "Account");
		clsCommonMobile.ClickButton(objDictionary, androidDriver, "Account", "Saved Credit Cards", 1);
		By card = AppiumBy.xpath("//android.widget.Button[contains(@content-desc, '****')]");
	    By emptyState = AppiumBy.accessibilityId("You have no saved credit cards");
	    By confirmDelete = AppiumBy.accessibilityId("Yes, Delete");
	    WebDriverWait wait = new WebDriverWait(androidDriver, Duration.ofSeconds(10));
	    //Remove all Credit Cards
	    while (true) {
	        wait.until(ExpectedConditions.or(
	                ExpectedConditions.presenceOfElementLocated(card),
	                ExpectedConditions.presenceOfElementLocated(emptyState)
	        ));

	        if (!androidDriver.findElements(emptyState).isEmpty()) {
	            System.out.println("No saved cards left.");
	            break;
	        }

	        WebElement row = androidDriver.findElement(card);
	        row.findElement(AppiumBy.className("android.widget.ImageView")).click();
	        wait.until(ExpectedConditions.elementToBeClickable(confirmDelete)).click();
	        wait.until(ExpectedConditions.invisibilityOfElementLocated(confirmDelete));
	    }
	    clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Saved Cards", "You have no saved credit cards", 1, "Exists", "");
	    clsCommonMobile.ClickButton(objDictionary, androidDriver, "Saved Cards", "Back", 1);
	}
	
	public void SENTRYMOBILE_Login(Map<String, String> objDictionary, AndroidDriver androiddriver, String strRole,String strLicensePlateNumber, String strWizardStatus, String strRemainMeStatus)
	{
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		CommonWeb clsCommonWeb = new CommonWeb();
		HttpConnections  clsHttpConnections = new HttpConnections ();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strUserName = strUniqueId+strMunicipality.replace(" ","").replace(",", "")+strRole+"@gmail.com";
		String strPassword = clsCommonWeb.SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		//Navigate to Accounts
 		clsCommonMobile.NavigateToPageUsingMenuButtons(objDictionary,androiddriver, "Account Details");
 		//Click the Sign In
 		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Login", "Sign In",1);
 		//Log In to CA
 		clsCommonMobile.PopulateAction(objDictionary, androiddriver, "Login", "Populate Login", "{T} Email Id|{T} Password|{CB} Remember me",strUserName.toLowerCase()+"|"+strPassword+"|"+strRemainMeStatus);
 		clsCommonMobile.ClickButton(objDictionary, androiddriver, "Login", "Log in",1);
		//Concierge Enabled
   		String strConciergeAdminSetting = clsHttpConnections.GET_GetConciergeAdminSetting(objDictionary, "enabled");
   		if(strConciergeAdminSetting.equals("true"))
   		{
   			try {Thread.sleep(2000);}catch (Exception e) {}
   			//Close Concierge Wizard (Enroll now, Enroll later, never show again)
   		   	String strConciergeState = clsHttpConnections.API_ReturnConciergeState(objDictionary,strRole,strLicensePlateNumber);
			String strEnrolledState = clsHttpConnections.GET_ConciergeEnrolledState(objDictionary, strRole) ;
			//Current Balance > 10
			String strCurrentParkingAccountBalance = objDictionary.get("strCurrentParkingAccountBalance");
			if(strCurrentParkingAccountBalance == null)
			{
				strCurrentParkingAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary, strRole);
			}
			Double.parseDouble(strCurrentParkingAccountBalance);
			try {Thread.sleep(1000);}catch (Exception e) {}
   		}
   	}
	
