	public void PEO_CreateManualViolationForDescriptionAndStatuteCodeValidation(Map<String, String> objDictionary, AppiumDriver androidDriver, String strViolationDescription, String strTicketAmountDue, String strSpotNumber)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		//Dictionary Variables
		String strDeviceId = objDictionary.get("strDeviceId");
		String[] arrMeterSpots = strDeviceId.split("-");
		String strMeterSpotName = "";
		if(strSpotNumber.equals("1")){strMeterSpotName = arrMeterSpots[0];}
		else
		{
			if(arrMeterSpots.length < 2){clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androidDriver,"This Test Requires dual meters-"+strMethondName);}
			else{strMeterSpotName = arrMeterSpots[1];}
		}
		if (!strSpotNumber.equals("1") && strMeterSpotName.equals("")) {strMeterSpotName = strDeviceId;}
		String strMunicipality = objDictionary.get("strMunicipality");
		if(strMunicipality.equals("Excelsior, MN")) {strViolationDescription = "Blocking Driveway";}
		Calendar cal = Calendar.getInstance();cal.add(Calendar.YEAR, 1);
		Date nextYear = cal.getTime();
	    String strNextYear = new SimpleDateFormat("yyyy").format(nextYear);
	    String strLicensePlateNumber = objDictionary.get("strLicensePlateNumber");
		String strLicensePlateState = objDictionary.get("strLicensePlateState");
		PEO_CreateManualViolation(objDictionary, androidDriver, strLicensePlateNumber, strLicensePlateState, strNextYear, "04", "AMC", strViolationDescription, strMeterSpotName, "Remark");
		try {Thread.sleep(1000);}catch (Exception e) {}
		String strWIFI = objDictionary.get("strWIFI");if(strWIFI == null) {strWIFI = "Enabled";}
		String strWIFIScanning = objDictionary.get("strWIFIScanning");if(strWIFIScanning == null) {strWIFIScanning = "Enabled";}
//  		if(strWIFI.equals("Disabled")||strWIFI.equals("Disabled")){clsCommonMobile.ClickButton(objDictionary, androidDriver, "New Violations", "No thanks", 1);}
		ClickButton(objDictionary, androidDriver, "Ticket", "Issued", 1);
	}
