	public void PEO_CreateManualViolation(Map<String, String> objDictionary, AppiumDriver androidDriver, String strLicensePlate, String strLicensePlateState, String strRegistrationExpYear, String strRegistrationExpMonth, String strVehicleMake, String strViolationReason, String strSpotId, String strRemarks)
	{
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		ClickButton(objDictionary, androidDriver, "New Violations", "Menu", 1);
		ClickLink(objDictionary, androidDriver, "New Violations", "Create Violation", 1);
		PEO_PopulateVehicleDetails(objDictionary, androidDriver,strLicensePlate, strLicensePlateState, strRegistrationExpYear, strRegistrationExpMonth, strVehicleMake);
		PEO_PopulateViolationDetails(objDictionary, androidDriver, strViolationReason, strSpotId, strRemarks);
		WebElement objTicketFrame = androidDriver.findElement(By.xpath(".//android.widget.ScrollView[1]"));
		ElementSwipe  clsElementSwipe  = new ElementSwipe();
		String strNumberOfViolationImages = objDictionary.get("strNumberOfViolationImages");if(strNumberOfViolationImages == null) {strNumberOfViolationImages = "0";}
		if(!strNumberOfViolationImages.equals("0"))
		{
			int intNumberOfViolationImages = Integer.parseInt(strNumberOfViolationImages);
			for(int intViolationCount = 1; intViolationCount<= intNumberOfViolationImages; intViolationCount++)
			{
				//Add 1st Violation Picture
				if(intViolationCount > 2)
				{clsCommonMobile.ClickButton(objDictionary, androidDriver, "Create Violation", "Add Photo",1);}
				try {Thread.sleep(1000);}catch (Exception e) {}
				clsCommonMobile.ClickButton(objDictionary, androidDriver, "Create Violation", "Violation Photo",1);
				//Not Now Button
//				String strWIFI = objDictionary.get("strWIFI");if(strWIFI == null) {strWIFI = "Enabled";}
//				String strWIFIScanning = objDictionary.get("strWIFIScanning");if(strWIFIScanning == null) {strWIFIScanning = "Enabled";}
//		  		if(strWIFI.equals("Disabled")||strWIFI.equals("Disabled") && intViolationCount < 3)
//		  		{
//		  			clsCommonMobile.ClickButton(objDictionary, androidDriver, "Create Violation", "Not now",1);
//				}
				clsCommonMobile.ClickButton(objDictionary, androidDriver, "Create Violation", "Picture Button",1);
				clsCommonMobile.ClickLink(objDictionary, androidDriver, "Create Violation", "OK", 1);
				objTicketFrame = androidDriver.findElement(By.xpath(".//android.widget.ScrollView[1]"));
				clsElementSwipe.Swipe_Flutter(androidDriver,objTicketFrame,"SWIPE_UP");
				WebElement objPictureFrame = androidDriver.findElement(By.xpath("//android.view.View[@content-desc=\"Violation Details:\nViolation Photos:\"]/android.view.View/android.view.View"));
				clsElementSwipe.Swipe_Flutter(androidDriver,objPictureFrame,"SWIPE_LEFT");
				if(intViolationCount > 5)//Additional Swipe need to center image.
				{
					clsElementSwipe.Swipe_Flutter(androidDriver,objPictureFrame,"SWIPE_LEFT");
				}
			}
		}
		else
		{
			objTicketFrame = androidDriver.findElement(By.xpath(".//android.widget.ScrollView[1]"));
			clsElementSwipe.Swipe_Flutter(androidDriver,objTicketFrame,"SWIPE_UP");
		}
		try {Thread.sleep(3500);}catch (Exception e) {}
 		ClickButton(objDictionary, androidDriver, "Create Violation", "Generate Ticket", 1);
 	}

