		PopulateAction(objDictionary, androidDriver, "Create Violation", "Populate VIN Number", "{T} VIN Number", "1N4961EZXT2744492");
		PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Registration Details Year", strRegistrationExpYear);
		PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Registration Details Month", strRegistrationExpMonth);
		PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Registration Details Day", "21");
		PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Registration type", strRandomUserRegistrationType);
		PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Vehicle body type", strRandomVehicleBodyType);
		PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Vehicle make", strVehicleMake);
