	public void PEO_ValidateViolationRemoved(Map<String, String> objDictionary, AppiumDriver androidDriver, String strViolationId)
	{
	    String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
	    Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
	    CommonANDROID_Flutter clsCommonMobile = new CommonANDROID_Flutter();
	    int intTextIndex = 1;
	    long startTime = System.currentTimeMillis();
	    long timeoutMillis = 30000; // 30 seconds
	    String strCondition = clsCommonMobile.ConditionalStepText(objDictionary, androidDriver, "Violation Details", "Violation Number", intTextIndex, "Exists", "");
	    if (strCondition.equals("True"))
	    {
	        String strValidated = "True";
	        boolean violationStillPresent = false;
	        do
	        {
	            // Check for timeout
	            if (System.currentTimeMillis() - startTime > timeoutMillis)
	            {
	            	clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Violation Details", "No violations to show", 1, "Exists", "");
	                return; // or throw exception if you prefer
	            }
	            String strClaimedViolationId = clsCommonMobile.StoreText(objDictionary, androidDriver, "Violation Details", "Violation Number", intTextIndex, "strClaimViolationId");
	            if (strClaimedViolationId.equals(strViolationId))
	            {
	                violationStillPresent = true;
	                clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androidDriver,"The Violation (" + strViolationId + ") was not removed from the violation list");
	            }
	            intTextIndex++;
	            strValidated = clsCommonMobile.ConditionalStepText(objDictionary, androidDriver, "Violation Details", "Violation Number", intTextIndex, "Exists", "");
	        } while (strValidated.equals("True"));
	        if (!violationStillPresent)
	        {Reporter.log("The Violation (" + strViolationId + ") was removed correctly");}
	    }
	    else
	    {clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Violation Details", "No violations to show", 1, "Exists", "");}
	}
	
	public void PEO_PopulateViolationDetails(Map<String, String> objDictionary, AppiumDriver androidDriver,String strViolationReason, String strSpotId, String strRemarks) 
	{
	    HttpConnections clsHttpConnections = new HttpConnections();
	    String strMethondName = new Object() {}.getClass().getEnclosingMethod().getName();
	    Reporter.log("<font color='orange'>     " + strMethondName + "</font>");
	    WebElement objTicketFrame = androidDriver.findElement(By.xpath(".//android.widget.ScrollView[1]"));
	    ElementSwipe clsElementSwipe = new ElementSwipe();
	    clsElementSwipe.Swipe_Flutter(androidDriver, objTicketFrame, "SWIPE_UP");
	    // Get ExternalViolationReason
	    String strExternalViolationReason = "";
	    try {strExternalViolationReason = clsHttpConnections.Json_ExternalViolationId(objDictionary, strViolationReason);} catch (Exception e) {}
	    PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Violation reason", strExternalViolationReason);
	    if (strViolationReason.equals("Expired Inspection Over 60 Days")) 
	    {
	        ClickTextfield(objDictionary, androidDriver, "Create Violation", "Inspection date", 1);
	        // ==================== MODERN DATE PICKER ====================
	        Calendar cal = Calendar.getInstance();
	        SimpleDateFormat sdf = new SimpleDateFormat("MM/dd/yy");
	        String strExpireOn = sdf.format(cal.getTime());
	        String strCurrentMth = new SimpleDateFormat("MMM", Locale.US).format(cal.getTime());
	        //strCurrentMth = "Apr";
	        String strCurrentYr = new SimpleDateFormat("yyyy").format(cal.getTime());
	        System.out.println("Setting Inspection Date: " + strCurrentMth + " " + strCurrentYr);
	        selectInWheel(androidDriver, strCurrentMth, 1); // Month Wheel
	        //selectInWheel(androidDriver, strCurrentYr, 3);  // Year Wheel
	        ClickButton(objDictionary, androidDriver, "Create Violation", "Set", 1);
	        // ===========================================================
	        PopulateAction(objDictionary, androidDriver, "Create Violation", "Populate Inspection number","{T} Inspection number", "407");
	        PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Spot ID", strSpotId);
	        PopulateAction(objDictionary, androidDriver, "Create Violation", "Populate Remarks", "{T} Remarks",strRemarks);
		    objDictionary.put("strOfficerNotes", "Inspection number 407  Expired on: "+strExpireOn+" Remark");
	    }
	    else
	    {
		    PopulateScrollableListbox(objDictionary, androidDriver, "Create Violation", "Spot ID", strSpotId);
		    PopulateAction(objDictionary, androidDriver, "Create Violation", "Populate Remarks", "{T} Remarks",strRemarks);
		    objDictionary.put("strOfficerNotes", "Remark");
	    }
	}
	
	private void selectInWheel(AppiumDriver androidDriver, String value, int scrollViewIndex) 
	{
		//This code is not working.
	    String xpath = String.format("//android.widget.ScrollView[%d]//android.view.View[@content-desc='%s']",scrollViewIndex, value);
	    for (int attempt = 0; attempt < 10; attempt++) {
	        try {
	            WebElement element = androidDriver.findElement(By.xpath(xpath));
	            if (element.isDisplayed()) 
	            {
	                element.click();
	                Thread.sleep(500);
	                return;
	            }
	        } catch (Exception ignored) {
	            scrollWheel(androidDriver, scrollViewIndex);
	            try {Thread.sleep(600);} catch (Exception e) {}
	        }
	    }
	    throw new RuntimeException("Could not select '" + value + "' in wheel " + scrollViewIndex);
	}

	private void scrollWheel(AppiumDriver androidDriver, int scrollViewIndex) 
	{
	    WebElement scrollView = androidDriver.findElement(By.xpath("//android.widget.ScrollView[" + scrollViewIndex + "]"));
	    int centerX = scrollView.getLocation().getX() + (scrollView.getSize().getWidth() / 2);
	    int startY = scrollView.getLocation().getY() + (scrollView.getSize().getHeight() * 75 / 100);
	    int endY = scrollView.getLocation().getY() + (scrollView.getSize().getHeight() * 30 / 100);
	    PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
	    Sequence swipe = new Sequence(finger, 0);
	    swipe.addAction(finger.createPointerMove(Duration.ofMillis(0), PointerInput.Origin.viewport(), centerX, startY));
	    swipe.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
	    swipe.addAction(finger.createPointerMove(Duration.ofMillis(600), PointerInput.Origin.viewport(), centerX, endY));
	    swipe.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));
	    androidDriver.perform(Collections.singletonList(swipe));
	}
	
