	public void VALIDATIONS_MeterPayment_MaxTime(Map<String, String> objDictionary,AppiumDriver androidDriver, int intRemainingFreeMinutes, int intRemainingMaxDuration, int intPreviousTimePurchased)
	{
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		Meter clsMeter = new Meter();
		String strMeterReboot = objDictionary.get("strMeterReboot");if(strMeterReboot == null) {strMeterReboot = "False";}
		if(strMeterReboot.equals("True"))
		{
			intRemainingMaxDuration = intRemainingMaxDuration - 5;
		}
		//Handles Rate to Free
		String strMinutesBeforeFreeParking = objDictionary.get("strMinutesBeforeFreeParking");
		if (strMinutesBeforeFreeParking != null)
		{
			String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
			intRemainingMaxDuration = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null,strMinutesBeforeFreeStart);
		}
		int intMeterMax  = 0;
		if(intPreviousTimePurchased == 0)
		{
			intMeterMax = intRemainingFreeMinutes + intRemainingMaxDuration - intPreviousTimePurchased;
		}
		else
		{
			String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment"); if(strFreeTimeFirstPayment == null) {strFreeTimeFirstPayment = "0";}
			//intMeterMax = intRemainingMaxDuration - intPreviousTimePurchased - Integer.parseInt(strFreeTimeFirstPayment);
			intMeterMax = intRemainingMaxDuration - intPreviousTimePurchased - Integer.parseInt(strFreeTimeFirstPayment);
		}
		int intMeterMaxMinusTwo = intMeterMax - 2;
		int intMeterMaxMinusOne = intMeterMax - 1;
		int intMeterMaxPlusOne = intMeterMax + 1;
		int intMeterMaxPlusTwo= intMeterMax + 2;
		String strMeterMaxRemainingWithValidTimePurchased = "Max Parking Time: "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterMax));
		String strMeterMaxRemainingWithValidTimePurchasedMinusTwo = "Max Parking Time: "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterMaxMinusTwo));
		String strMeterMaxRemainingWithValidTimePurchasedMinusOne = "Max Parking Time: "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterMaxMinusOne));
		String strMeterMaxRemainingWithValidTimePurchasedPlusOne = "Max Parking Time: "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterMaxPlusOne));
		String strMeterMaxRemainingWithValidTimePurchasedPlusTwo = "Max Parking Time: "+clsCommonMobile.SENTRYMOBILE_ConvertMinutesToHrsAndMins(Integer.toString(intMeterMaxPlusTwo));
		String strActualMaxtime = clsCommonMobile.StoreText(objDictionary, androidDriver, "Choose Parking Duration", "Max Parking Time", 1, "strActualMaxtime");
		//Validate Max Time
		if(strActualMaxtime.equals(strMeterMaxRemainingWithValidTimePurchased))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxRemainingWithValidTimePurchased + ")-Actual");}
		else if(strActualMaxtime.equals(strMeterMaxRemainingWithValidTimePurchasedMinusOne))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxRemainingWithValidTimePurchasedMinusOne + ")-Minus1");}
		else if(strActualMaxtime.equals(strMeterMaxRemainingWithValidTimePurchasedMinusTwo))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxRemainingWithValidTimePurchasedMinusTwo + ")-Minus2");}
		else if(strActualMaxtime.equals(strMeterMaxRemainingWithValidTimePurchasedPlusOne))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxRemainingWithValidTimePurchasedPlusOne + ")-Plus1");}
		else if(strActualMaxtime.equals(strMeterMaxRemainingWithValidTimePurchasedPlusTwo))
		{Reporter.log("The Text (Max time) with index (1) equaled (" + strMeterMaxRemainingWithValidTimePurchasedPlusTwo + ")-Plus2");}
		else
		{clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, androidDriver,"The Text (Max time) with index (1) did not equal (" + strMeterMaxRemainingWithValidTimePurchased + ") - actual value (" + strActualMaxtime + ")");}
	}
	public String SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee(Map<String, String> objDictionary,AppiumDriver androidDriver, String strParkingFee,String strSpotNumber)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		HttpConnections clsHttpConnections = new HttpConnections();
		//Get Fees At Time of Purchase
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strDeviceId = objDictionary.get("strDeviceId");
		String[] arrMeterSpots = strDeviceId.split("-");
		String strMeterSpotName = "";
		if(strSpotNumber.equals("1")){strMeterSpotName = arrMeterSpots[0];}else{strMeterSpotName = arrMeterSpots[1];}
  		//Check if Lot Screen Displays
		clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Spot", 1, "Contains", strMeterSpotName);
		String strFirstPaymentFee = objDictionary.get("strFirstPayment");
		if(strFirstPaymentFee == null){strFirstPaymentFee = "0";}
		String strCurrentMeterTime = objDictionary.get("strCurrentMeterTime");if(strCurrentMeterTime == null){strCurrentMeterTime = "0";}
		double dblParkingFee = Double.parseDouble(strParkingFee.replace("$",""));
		double dblConvenienceFee = Double.parseDouble(strFirstPaymentFee)*.01;
		String strHandicapPermit = objDictionary.get("strHandicapPermit");
		double dblTotalFee = dblParkingFee;
		if(strHandicapPermit == null) {dblTotalFee = dblParkingFee + dblConvenienceFee;}
		DecimalFormat dFormat = new DecimalFormat("$ 0.00");
		strParkingFee = dFormat.format(dblParkingFee);
		VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Parking Fee", 1, "Value", dFormat.format(dblParkingFee));
		if(strHandicapPermit == null)
		{
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Convenience Fee", 1, "Value", dFormat.format(dblConvenienceFee));
			objDictionary.remove("strConveninceFee");objDictionary.put("strConveninceFee", dFormat.format(dblConvenienceFee));
		}
		else
		{
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Convenience Fee", 1, "Value", "$ 0.00");
			objDictionary.remove("strConveninceFee");objDictionary.put("strConveninceFee", "$ 0.00");
		}
		VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Total Fee", 1, "Value", dFormat.format(dblTotalFee));
		objDictionary.put("strTotalFee", dFormat.format(dblTotalFee));
		return dFormat.format(dblTotalFee);
	}
	public String SENTRYMOBILE_ValidateSubsequentPaymentDialogAndReturnParkingFee(Map<String, String> objDictionary,AppiumDriver androidDriver, String strTotalFee)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonANDROID_Flutter  clsCommonMobile = new CommonANDROID_Flutter();
		HttpConnections clsHttpConnections = new HttpConnections();
		//Get Fees At Time of Purchase
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strMeterSpotName = objDictionary.get("strMeterSpotName");
		clsCommonMobile.VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Spot", 1, "Contains", strMeterSpotName);
		String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
		if(strSubsequentPayment == null){strSubsequentPayment = "0";}
		String strParkingFee = strTotalFee;
		DecimalFormat dFormat = new DecimalFormat("$ 0.00");
		if(strSubsequentPayment.equals("0"))
		{
			double dblParkingFee = Double.parseDouble(strParkingFee.replace("$",""));
			double dblConvenienceFee = Double.parseDouble(strSubsequentPayment)*.01;
			double dblTotalFee = dblParkingFee + dblConvenienceFee;
			strParkingFee = dFormat.format(dblParkingFee);
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format(dblParkingFee));
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Total Fee", 1, "Contains", dFormat.format(dblTotalFee));
			return String.valueOf(dFormat.format(dblTotalFee));
		}
		else
		{
			double dblParkingFee = Double.parseDouble(strParkingFee.replace("$",""));
			double dblConvenienceFee = Double.parseDouble(strSubsequentPayment)*.01;
			double dblTotalFee = dblParkingFee + dblConvenienceFee;
			strParkingFee = dFormat.format(dblParkingFee);
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format(dblParkingFee));
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(dblConvenienceFee));
			VerificationPointText(objDictionary, androidDriver, "Review and Pay", "Total Fee", 1, "Contains", dFormat.format(dblTotalFee));
			objDictionary.put("strTotalFee", dFormat.format(dblTotalFee));
			return String.valueOf(dFormat.format(dblTotalFee));
		}
	}
	
