	public String ConditionalStepButton(Map<String, String> objDictionary, AppiumDriver androidDriver, String strPageName, String strButtonName, int intButtonIndex, String strValidationType, String strTextVaue)
    {
		WebElement objButton = GetButtonObj(objDictionary, androidDriver, strPageName, strButtonName,intButtonIndex);
		if (objButton != null)
        {   
            switch (strValidationType)
            {
                case "Disabled":
                    if (!objButton.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                    return "False";
                case "Enabled":
                    if (objButton.isEnabled()) { return "True"; } else { return "False"; } 
                case "Exists":
                    return "True";
                case "Visible":
                    if (objButton.isDisplayed()) { return "True"; } else { return "False"; } 
                case "Invisible":
                    if (objButton.isDisplayed()) { return "True"; } else { return "False"; }
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The validation type (" + strValidationType + ") hasn't been coded yet - ConditionalStepButton.cs");
             }
        }
        else
        {
            switch (strValidationType)
            {
                case "Does Not Exist":
                    return "True";
                case "Exists":
                    return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The button (" + strButtonName + ") at index (" + intButtonIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
        }
        return "";
    }   
	public String ConditionalStepCheckbox(Map<String, String> objDictionary, AppiumDriver androidDriver, String strPageName, String strCheckboxGroup, String strCheckboxName, int intCheckboxIndex, String strValidationType, String strCheckboxValue)
    {
		strCheckboxName = ConvertValues(objDictionary, androidDriver, strCheckboxName);
		WebElement objCheckbox = GetCheckboxObj(objDictionary,androidDriver, strPageName, strCheckboxGroup, strCheckboxName, Integer.toString(intCheckboxIndex));
		if (objCheckbox != null)
	    {   
            switch (strValidationType)
            {
                case "Disabled":
                    if (!objCheckbox.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                    return "False";
                case "Enabled":
                    if (objCheckbox.isEnabled()) { return "True"; } else { return "False"; } 
                case "Exists":
                    return "True";
                case "Visible":
                    if (objCheckbox.isDisplayed()) { return "True"; } else { return "False"; } 
                case "Invisible":
                    if (objCheckbox.isDisplayed()) { return "True"; } else { return "False"; }
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The validation type (" + strValidationType + ") hasn't been coded yet - ConditionalStepLink.cs");
            }
        }
        else
        {
            switch (strValidationType)
            {
                case "Does Not Exist":
                    return "True";
                case "Exists":
                    return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Checkbox (" + strCheckboxName + ") at index (" + intCheckboxIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
        }
        return "";
    }   
	public String ConditionalStepLink(Map<String, String> objDictionary, AppiumDriver androiddriver, String strPageName, String strLinkName, int intLinkIndex, String strValidationType, String strTextVaue)
    {
		WebElement objLink = GetLinkObj(objDictionary, androiddriver, strPageName, strLinkName);
		if (objLink != null)
        {   
            switch (strValidationType)
            {
                case "Disabled":
                    if (!objLink.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                    return "False";
                case "Enabled":
                    if (objLink.isEnabled()) { return "True"; } else { return "False"; } 
                case "Exists":
                    return "True";
                case "Visible":
                    if (objLink.isDisplayed()) { return "True"; } else { return "False"; } 
                case "Invisible":
                    if (objLink.isDisplayed()) { return "True"; } else { return "False"; }
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The validation type (" + strValidationType + ") hasn't been coded yet - ConditionalStepLink.cs");
            }
        }
        else
        {
            switch (strValidationType)
            {
                case "Does Not Exist":
                    return "True";
                case "Exists":
                    return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The link (" + strLinkName + ") at index (" + intLinkIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
        }
        return "";
    }   
	public String ConditionalStepTable(Map<String, String> objDictionary,AndroidDriver androiddriver, String strPageName, String strTableName, int intTableIndex, String strValidationType, String strTableVaue, int intRowNumber, int intColumnNumber)
    {
		WebElement objTable = GetTableObj(objDictionary,androiddriver, strPageName, strTableName, intTableIndex);
		if (objTable == null){UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The table (" + strTableName + ") with index (" + intTableIndex + ") did not exist)-ConditionalStepTable");}
		switch (strValidationType)
        {
			case "ColumnValueExists":
				intRowNumber = 1;
				if(objTable.findElements(By.xpath("//tbody/tr")).size() > 0)
				{
					WebElement objTableRow = objTable.findElement(By.xpath("//tr["+intRowNumber+"]")); 
					if(objTableRow.findElements(By.xpath("//tr["+intRowNumber+"]//td")).size() >= intColumnNumber)
					{
						List<WebElement> allRows = objTable.findElements(By.xpath("//tr["+intRowNumber+"]")); 
						for (WebElement row : allRows) 
						{ 
						 	List<WebElement> cells = row.findElements(By.xpath("//td["+intColumnNumber+"]"));
						    for (WebElement cell : cells){if(cell.getText().equalsIgnoreCase(strTableVaue)){return "True";}}
						}
					}
				}
				else
				{
					UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"There was no rows in the ("+strTableName+") table");
				}
				return "False";
			default:
				UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Table validation type (" + strValidationType + ") hasn't been coded yet - ConditionalStepTable");
        }
		return "";
    }
	public String ConditionalStepText(Map<String, String> objDictionary,AppiumDriver androidDriver, String strPageName, String strTextName, int intTextIndex, String strValidationType, String strTextVaue)
    {  
		WebElement objText = GetTextObj(objDictionary,androidDriver,strPageName,strTextName,intTextIndex);
		if (objText != null)
	    {
			switch (strValidationType)
            {
				case "Contains":
					if(objText.getText().contains(strTextVaue)){ return "True"; } else { return "False"; }
	            	case "Does Not Exist":
		            	return "False";
		            case "Exists":
		            	return "True";
		            case "Value":
		            	if(objText.getText().trim().equals(strTextVaue)){ return "True"; } else { return "False"; }
	                default:
	                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text validation type (" + strValidationType + ") hasn't been coded yet - ConditionalStepText");
            }
		}
	    else
	    {
	    	switch (strValidationType)
            {
                case "Does Not Exist":
                	return "True";
                case "Exists":
                	return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
	    }
		return "";
    } 
	public String ConditionalStepTextField(Map<String, String> objDictionary, AppiumDriver androidDriver, String strPageName, String strTextFieldName, int intTextFieldIndex, String strValidationType, String strTextFieldValue)
    {  
		WebElement objTextField = GetTextFieldObj(objDictionary, androidDriver, strPageName, strTextFieldName);
		if (objTextField != null)
	    {
			switch (strValidationType)
            {
            	case "Value":
            		if(objTextField.getText().equals(strTextFieldValue)){ return "True"; } else { return "False"; }
            	case "Disabled":
                    if (!objTextField.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                	return "False"; 
	            case "Enabled":
	            	if (objTextField.isEnabled()) { return "True"; } else { return "False"; }
	            case "Exists":
	            	return "True";
	            default:
	            	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The TextField validation type (" + strValidationType + ") hasn't been coded yet - ConditionalStepTextField");
            }
		}
	    else
	    {
	    	switch (strValidationType)
            {
                case "Does Not Exist":
                	return "True";
                case "Exists":
                	return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Textfield (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
	    }
		return "";
    } 
	
