	public void VerificationPointText(Map<String, String> objDictionary, AppiumDriver androidDriver, String strPageName, String strTextName, int intTextIndex, String strValidationType, String strTextVaue)
    {
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objText = GetTextObj(objDictionary,androidDriver,strPageName,strTextName,intTextIndex);
		if (objText == null)
		{
			System.out.println("objText is null"); 
		}
		strTextVaue = ConvertValues(objDictionary, androidDriver, strTextVaue);
		if (objText != null)
	    {
			switch (strValidationType)
            {
				case "Contains":
					try {
					    // Get text with fallback strategy (prioritizing .getText())
					    String strObjectText = objText.getText();  // Primary: Use getText() first
					    // Fallbacks only if getText() returns null or empty
					    if (strObjectText == null || strObjectText.trim().isEmpty()) {
					        strObjectText = objText.getAttribute("content-desc");
					    }
					    if (strObjectText == null || strObjectText.trim().isEmpty()) {
					        strObjectText = objText.getAttribute("name");
					    }
					    if (strObjectText == null || strObjectText.trim().isEmpty()) {
					        strObjectText = objText.getAttribute("contentDescription");
					    }
					    // Clean the text
					    strObjectText = (strObjectText != null) ? strObjectText.replaceAll("[\\r\\n]+", " ").trim() : "";
					    // Validation
					    if (strObjectText.contains(strTextVaue)) 
					    {Reporter.log("The Text (" + strTextName + ") with index (" + intTextIndex + ") contained (" + strTextVaue + ")");}
					    else 
					    {UpdateErrorMessageWithPivotalData(objDictionary, androidDriver, "The Text (" + strTextName + ") with index (" + intTextIndex + ") did not contain (" + strTextVaue + ") - actual value (" + strObjectText + ")");}
					} 
					catch (Exception a) 
					{UpdateErrorMessageWithPivotalData(objDictionary, androidDriver,"The Text (" + strTextName + ") with index (" + intTextIndex + ") existed, but failed to retrieve text");}
					return;
            	case "Disabled":
	                if (!objText.isEnabled()){Reporter.log("The Text (" + strTextName + ") at index (" + intTextIndex + ") was disabled");}
	                else
	                {UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text  (" + strTextName + ") at index (" + intTextIndex + ") was not disabled");}
        			return;
	            case "Does Not Exist":
		            UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") existed");
	            case "Enabled":
	            	if (objText.isEnabled()){Reporter.log("The Text (" + strTextName + ") at index (" + intTextIndex + ") was enabled"+"");}
	            	else
	            	{UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") was not enabled");}
	            	return;
	            case "Exists":
	            	Reporter.log("The Text (" + strTextName + ") at index (" + intTextIndex + ") existed"+"");
	                return;
	            case "Value":
            		String strActualTextValue = "";
            		try {strActualTextValue = objText.getAttribute("content-desc").trim().replace("\n", "");} catch (Exception a) 
            		{UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") did not have a text value-"+strMethodName);}
            		if(strActualTextValue.trim().equals(strTextVaue.trim()))
            		{Reporter.log("The Text (" + strTextName + ") with index (" + intTextIndex + ") equaled (" + strTextVaue + ")"+"");}
            		else
            		{UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") with index (" + intTextIndex + ") did not equal (" + strTextVaue + ") - actual value (" + strActualTextValue + ")");}
            		return;
	            default:
	            	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text validation type (" + strValidationType + ") hasn't been coded yet - VerificationPointText");
            		return;
	        }
		}
	    else
	    {
	    	switch (strValidationType)
            {
                case "Does Not Exist":
                	Reporter.log("The Text  (" + strTextName + ") at index (" + intTextIndex + ") did not exist"+"");
	                return;
                case "Exists":
                	UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") did not exist");
	            default:
	                UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
	    }
    } 
	
