	public String StoreTextField(Map<String, String> objDictionary, AppiumDriver androidDriver, String strPageName, String strTextFieldName, int intTextFieldIndex, String strVariableName)
	{
		String strTextFieldValue = "";
		WebElement objTextField = GetTextFieldObj(objDictionary, androidDriver, strPageName, strTextFieldName);
		if (objTextField == null)
		{
			UpdateErrorMessageWithPivotalData(objDictionary,androidDriver,"The Textfield (" + strTextFieldName + ") with index (" + intTextFieldIndex + ") did not exist)");
		}
		switch (strTextFieldName)
	    {
			default:
				 if (!objTextField.getText().equals(""))
                 {
                     switch (strSpecialInstruction)
                     {
                         case "outerText":
                             strTextFieldValue = objTextField.getAttribute("outerText");
                             break;
                         default:
                             strTextFieldValue = objTextField.getText().replace("\n", "").replace("\r", "").trim();
                             break;
                     }
                 }
	    }
		objDictionary.remove(strVariableName);
		objDictionary.put(strVariableName, strTextFieldValue);
		Reporter.log("The Textfield (" + strTextFieldName + ") value (" + strTextFieldValue + ") was stored as variable name (" + strVariableName + ")"+"");
		return strTextFieldValue;
	}
	//**********************
	//Convert Commands
	//**********************
	public String ConvertValues(Map<String, String> objDictionary, AppiumDriver androiddriver, String strValue)
	{
		try
		{
			if (strValue != null)
			{
				//Date Match
				String strDatePattern = "(#[-0-9]*\\|[-0-9]*\\|[-0-9]*\\|.*#)";
			    Pattern pDate = Pattern.compile(strDatePattern);
			    Matcher mDate = pDate.matcher(strValue);
			    //Variable Match
			    String strVariablePattern = "~.*~";
			    Pattern pVariable = Pattern.compile(strVariablePattern);
			    Matcher mVariable = pVariable.matcher(strValue);
			    while (mDate.find( )||mVariable.find( )) 
			    {
				    	int intFirstDateCharacter = strValue.indexOf("#") + "#".length();
				    	int intFirstTilde = strValue.indexOf("~") + "~".length();
				    	if (intFirstDateCharacter != 0){strValue = ConvertDateFormat(strValue, intFirstDateCharacter);}
				    	if (intFirstTilde != 0){strValue = ConvertVariable(objDictionary, strValue, intFirstTilde);}
			    }
			}
		}
		catch (Exception e){}
		try{strValue = strValue.replace("[tilda]", "~");}
		catch (Exception e){}
		if(strValue == null)
		{
			System.out.println("MIH");
		}
		return strValue.trim();
	}
	public String ConvertDateFormat(String strDataValue,int intFirstDateCharacter)
    {	
		String[] arrDateValues = strDataValue.replace("#", "").split("[|]", 10);
		Date dateCurrent = new Date();
		DateFormat dateFormat = new SimpleDateFormat(arrDateValues[3]);
		System.out.println(dateFormat.format(dateCurrent));
		int intMonthValue = Integer.parseInt(arrDateValues[0]);
		int intDayValue = Integer.parseInt(arrDateValues[1]);
		int intYearValue = Integer.parseInt(arrDateValues[2]);
		dateCurrent = addDay(dateCurrent, intDayValue); 
		dateCurrent = addMonth(dateCurrent, intMonthValue); 
		dateCurrent = addYear(dateCurrent, intYearValue); 
		strDataValue = dateFormat.format(dateCurrent);
		System.out.println(dateFormat.format(dateCurrent)); //2014/08/06 15:59:48
		return strDataValue;
    }
	public String ConvertVariable(Map<String, String> objDictionary, String strValue,int intFirstDateCharacter)
	{
		String strVariableValue = objDictionary.get(strValue.replaceAll("~", ""));
		if(strVariableValue == null)
		{
	     	UpdateErrorMessageWithPivotalData(objDictionary,null,"The variable ("+strValue.replaceAll("~", "")+") did not exist in the objDictionary");
	        return null;
		}
		return strVariableValue;
	}
	public static Date addDay(Date date, int i) 
	{
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);
        cal.add(Calendar.DAY_OF_YEAR, i);
        return cal.getTime();
    }
    public static Date addMonth(Date date, int i) 
    {
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);
        cal.add(Calendar.MONTH, i);
        return cal.getTime();
    }
    public static Date addYear(Date date, int i) 
    {
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);
        cal.add(Calendar.YEAR, i);
        return cal.getTime();
    }
    public String SENTRYMOBILE_ConvertMinutesToHrsAndMins(String strMinutes)
	{
		int intMinutes = Integer.parseInt(strMinutes);
		if (intMinutes > 60)
		{
			int hours = intMinutes / 60;
			int minutes = intMinutes % 60;
			if(minutes == 0)
			{strMinutes = Integer.toString(hours)+"hr";}
			else
			{strMinutes = Integer.toString(hours)+"hr "+Integer.toString(minutes)+ "min(s)";}
		}
		else
		{strMinutes = strMinutes+ "min(s)";}
		return strMinutes;
	}           	
    public String AddTimeToExistingTime(String strTime, String strPlusMinutes,String strDateFormat)
	{
		String newTime = "";
		try
		{
			DateFormat sdf = new SimpleDateFormat(strDateFormat);
			Date startDate = sdf.parse(strTime);
			Calendar cal = Calendar.getInstance();
			cal.setTime(startDate);
			cal.add(Calendar.MINUTE, Integer.parseInt(strPlusMinutes));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e) 
		{
			System.out.println("MIH");
		}
		return newTime;
	}
    public String SubtractTimeFromExistingTime(String strTime, String strMinusMinutes, String strDateFormat)
    {
        String newTime = "";
        try
        {
            DateFormat sdf = new SimpleDateFormat(strDateFormat);
            Date startDate = sdf.parse(strTime);
            Calendar cal = Calendar.getInstance();
            cal.setTime(startDate);
            
            // Subtract by using negative value
            cal.add(Calendar.MINUTE, -Integer.parseInt(strMinusMinutes));
            
            newTime = sdf.format(cal.getTime());
        }
        catch(Exception e) 
        {
            System.out.println("Error subtracting time: " + e.getMessage());
        }
        return newTime;
    }
    public String SENTRYMOBILE_ConvertMinutesToHrAndMins(String strMinutes) {
		//Ricky_ I removed the S in hours and added when needed
	    int intMinutes = Integer.parseInt(strMinutes);
	    if (intMinutes >= 60) {
	        int hours = intMinutes / 60;
	        int minutes = intMinutes % 60;
	        String hourStr = (hours == 1) ? " Hr " : " Hrs ";
	        strMinutes = hours + hourStr + Integer.toString(minutes);
	    }
	    return strMinutes;
	}
    public String SENTRYMOBILE_CreateRandomLicensePlateNumber()
	{
//		String strAutomationUser = System.getProperty("user.name");
//		return strAutomationUser.substring(0, 6).toUpperCase();
		Random r = new Random();
	    String alphabet = "1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ";
	    String LicencePlateNumber = "";
	    for (int i = 0; i < 6; i++) {LicencePlateNumber = LicencePlateNumber + alphabet.charAt(r.nextInt(alphabet.length()));}
	    return LicencePlateNumber;
	}
    
    //**********************
    //Store Values
    //**********************
    public String StoreText(Map<String, String> objDictionary, AppiumDriver androiddriver, String strPageName, String strTextName, int intTextIndex, String strVariableName)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strTextValue = "";
		WebElement objText = GetTextObj(objDictionary,androiddriver,strPageName,strTextName,intTextIndex);
		if (objText == null)
		{
			try {androiddriver.findElement(By.id("com.mpspark.consumer.mpsconsumer:id/textViewClose")).click();try {Thread.sleep(2000);}catch (Exception e) {} }catch(Exception a) {};
			UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The stored page text (" + strTextName + ") with index (" + intTextIndex + ") did not exist");
		}
		switch (strTextName)
	    {
			default:
				if(objText != null)
				{
					try
					{
						System.out.print(objText.getAttribute("content-desc"));
						if (!objText.getAttribute("content-desc").equals(""))
						{
		                     switch (strSpecialInstruction)
		                     {
		                     	case "alt":strTextValue = objText.getAttribute("alt");break;
		                     	case "outerText":strTextValue = objText.getAttribute("outerText");break;
		                     	default:
		                             strTextValue = objText.getAttribute("content-desc").replace("\n", " ").replace("\r", " ").trim();break;
		                     }
		                 }
					}
					catch (Exception e) 
					{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") does not exist-"+strMethodName);}
				}
				else
				{UpdateErrorMessageWithPivotalData(objDictionary,androiddriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") does not exist-"+strMethodName);}
	    }
		objDictionary.remove(strVariableName);
		objDictionary.put(strVariableName, strTextValue);
		//Reporter.log("The text name (" + strTextName + ") value (" + strTextValue + ") was stored as variable name (" + strVariableName + ")"+"");
		return strTextValue;
	}
    
    
