    	clsCommonMobile.SENTRYMOBILE_PurchaseMeterTimeParkThenPay(objDictionary, androidDriver,strFreeTimeFirstPayment,strMeterIncrementTime,"True","False");
    	//RP60: Remained Parked 60 seconds
    	clsMeter.METER_MeterWaitWithMessage(objDictionary,60, "Remained Parked For 60 seconds-Spot"+strSpotNumber);
       	//VPSVD: Validate Parking Session Values Decremented
    	String strActualRemainingTimeMinutes = objDictionary.get("strActualRemainingTimeMinutes");
    	int intMeterRemainingTimeMinutesMinusOne =  Integer.parseInt(strActualRemainingTimeMinutes) - 1;
    	String strParkingSessionDetails = objDictionary.get("strParkingSessionDetails");
    	String strExpectedParkingSession = strParkingSessionDetails.replace(strActualRemainingTimeMinutes+" mins", intMeterRemainingTimeMinutesMinusOne + " mins");
    	String strActualParkingSessionDetails = clsCommonMobile.StoreText(objDictionary, androidDriver, "Parking Sessions", "Parking Session Details", 1, "strActualParkingSessionDetails");
        if (strActualParkingSessionDetails.contains(strExpectedParkingSession)) 
		{
        	Reporter.log("The Text (" + strActualParkingSessionDetails + ") contained (" + strExpectedParkingSession + ")");
        	objDictionary.put("strParkingSessionDetails", strParkingSessionDetails);
        }
  		else 
  		{UpdateErrorMessageWithPivotalData(objDictionary, androidDriver, "The Text (" + strActualParkingSessionDetails + ") did not contain (" + strParkingSessionDetails + ") - actual value (" + strActualParkingSessionDetails + ")");}
        androidDriver.quit();
    	//ShortSessionWaitExitSpot
      	clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null,"1","Local");
